1	export type Item = { type: string; cursed?: boolean; enchantment?: number };
2	export type Step = { items: Item[] };
3	export type Customer = { yearsWithMHPCO: number };
4	export type Scenario = { customer: Customer; steps: Step[] };
5	export type Result = { premium: number };
6	export type ScenarioOutcome = { results: Result[] };
7	
8	const BASE_PREMIUMS: Record<string, number> = {
9	  sword: 100,
10	  amulet: 60,
11	  staff: 80,
12	  potion: 40,
13	  rune: 25,
14	  moonstone: 25,
15	};
16	
17	const FIRST_INSURANCE_SURCHARGE = 1.1;
18	const PROCESSING_FEE = 5;
19	
20	// Guards against binary-float artifacts (e.g. 52.800000000000004) tipping an
21	// exact value over a whole-gold boundary and inflating the premium by 1 G.
22	const FLOAT_ARTIFACT_PRECISION = 6;
23	
24	const roundUpToWholeGold = (amount: number): number =>
25	  Math.ceil(Number(amount.toFixed(FLOAT_ARTIFACT_PRECISION)));
26	
27	// Multipliers on the base premium, not amounts added to it.
28	const CURSED_RISK_FACTOR = 1.5;
29	const HIGH_ENCHANTMENT_RISK_FACTOR = 1.3;
30	const NO_ADDED_RISK = 1;
31	
32	const HIGH_ENCHANTMENT_LEVEL = 5;
33	
34	const isHighlyEnchanted = (item: Item): boolean =>
35	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
36	
37	// Risks compound: an item that is both cursed and highly enchanted carries
38	// both factors.
39	const riskFactorOf = (item: Item): number =>
40	  (item.cursed ? CURSED_RISK_FACTOR : NO_ADDED_RISK) *
41	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_RISK_FACTOR : NO_ADDED_RISK);
42	
43	// The price-list value adjusted for the item's own risk — not the bare
44	// BASE_PREMIUMS figure.
45	const riskAdjustedPremiumOf = (item: Item): number =>
46	  BASE_PREMIUMS[item.type] * riskFactorOf(item);
47	
48	const BUILDING_BLOCK_SIZE = 3;
49	const BUILDING_BLOCK_PREMIUM = 60;
50	
51	const areAlike = (items: Item[]): boolean =>
52	  items.every((item) => item.type === items[0].type);
53	
54	const sumOfPremiums = (items: Item[]): number =>
55	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
56	
57	// An unalike list forms no blocks at all, however many items it holds.
58	const buildingBlockCountOf = (items: Item[]): number =>
59	  areAlike(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
60	
61	// Alike items group into building blocks priced below the sum of their members'
62	// individual premiums; everything left over prices individually.
63	const blockPricedTotalOf = (items: Item[]): number => {
64	  const blocks = buildingBlockCountOf(items);
65	  const looseItems = items.slice(blocks * BUILDING_BLOCK_SIZE);
66	
67	  return blocks * BUILDING_BLOCK_PREMIUM + sumOfPremiums(looseItems);
68	};
69	
70	const LOYALTY_DISCOUNT_FACTOR = 0.8;
71	const LOYALTY_YEARS = 2;
72	const NO_DISCOUNT = 1;
73	
74	const isLongStanding = (customer: Customer): boolean =>
75	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
76	
77	const loyaltyFactorOf = (customer: Customer): number =>
78	  isLongStanding(customer) ? LOYALTY_DISCOUNT_FACTOR : NO_DISCOUNT;
79	
80	const REPEAT_CONTRACT_DISCOUNT_FACTOR = 0.85;
81	
82	// The first contract carries the initial assessment surcharge; every contract
83	// after it earns the repeat-contract discount instead.
84	const contractFactorOf = (contractIndex: number): number =>
85	  contractIndex === 0 ? FIRST_INSURANCE_SURCHARGE : REPEAT_CONTRACT_DISCOUNT_FACTOR;
86	
87	// Risk factors attach to a single item; these attach to the policy as a whole,
88	// so they multiply the block-priced total once rather than per item.
89	const policyFactorOf = (customer: Customer, contractIndex: number): number =>
90	  contractFactorOf(contractIndex) * loyaltyFactorOf(customer);
91	
92	// The fee is a flat charge on top of the rounded premium, so it sits outside
93	// the rounding rather than being rounded along with it.
94	const premiumFor = (step: Step, policyFactor: number): number =>
95	  roundUpToWholeGold(blockPricedTotalOf(step.items) * policyFactor) + PROCESSING_FEE;
96	
97	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
98	  results: scenario.steps.map((step, contractIndex) => ({
99	    premium: premiumFor(step, policyFactorOf(scenario.customer, contractIndex)),
100	  })),
101	});
